-- Padel and DHA Lahore, the area around LUMS. See docs/plan.md and docs/dha-padel-venues.md.

-- Padel games use the existing event flow; the value is only used by later transactions.
ALTER TYPE event_type ADD VALUE 'padel';

-- DHA's bounds come from its phases' places (no single outline is mapped).
INSERT INTO areas (id, name, type) VALUES ('00000000-0000-4000-8000-000000000100', 'DHA', 'district');
UPDATE areas SET parent_id = '00000000-0000-4000-8000-000000000100' WHERE id = '00000000-0000-4000-8000-000000000001';

